-- PERBAIKAN Kelas Arka. Aman dijalankan berkali-kali.
-- Supabase > SQL Editor > New query > tempel semua > Run
create table if not exists lessons (
  id text primary key, title text not null, emoji text, color text,
  sort_order int default 99, lang text default 'id',
  pages jsonb default '[]', questions jsonb default '[]');
create table if not exists results (
  id uuid primary key default gen_random_uuid(), created_at timestamptz default now(),
  lesson_id text, lesson_title text, lesson_emoji text,
  score int check (score between 0 and 100), correct int, total int, stars int, answers jsonb);
create table if not exists settings (id text primary key, child_name text, message text);
alter table lessons add column if not exists subject text;
alter table settings add column if not exists kid_username text;
alter table settings add column if not exists kid_pass_hash text;
alter table settings add column if not exists subjects jsonb;


-- Izin supaya website boleh membaca/mengirim data (sering belum aktif di project Supabase baru)
grant usage on schema public to anon, authenticated;
grant select on lessons, settings to anon, authenticated;
grant insert on results to anon, authenticated;
grant select, insert, update, delete on lessons, settings, results to authenticated;

alter table lessons enable row level security;
alter table results enable row level security;
alter table settings enable row level security;

drop policy if exists "baca pelajaran" on lessons;
drop policy if exists "mama ubah pelajaran" on lessons;
drop policy if exists "baca pengaturan" on settings;
drop policy if exists "mama ubah pengaturan" on settings;
drop policy if exists "kirim nilai" on results;
drop policy if exists "mama lihat nilai" on results;
drop policy if exists "mama hapus nilai" on results;
create policy "baca pelajaran" on lessons for select using (true);
create policy "mama ubah pelajaran" on lessons for all to authenticated using (true) with check (true);
create policy "baca pengaturan" on settings for select using (true);
create policy "mama ubah pengaturan" on settings for all to authenticated using (true) with check (true);
create policy "kirim nilai" on results for insert with check (true);
create policy "mama lihat nilai" on results for select to authenticated using (true);
create policy "mama hapus nilai" on results for delete to authenticated using (true);

insert into settings (id, child_name, message) values ('home','Arka','Semangat belajar ya, Nak! Mama sayang Arka. ❤️')
  on conflict (id) do nothing;
insert into lessons (id,title,emoji,color,sort_order,lang,pages,questions) values
('perkalian','Perkalian Seru','✖️','coral',1,'id',$j$[{"emoji": "🍪🍪🍪 🍪🍪🍪", "text": "Perkalian adalah penjumlahan berulang.\n2 piring, masing-masing 3 kue:\n3 + 3 = 6, jadi 2 × 3 = 6."}, {"emoji": "🔄", "text": "Urutan bisa ditukar dan hasilnya sama.\n4 × 5 = 20 dan 5 × 4 = 20."}, {"emoji": "0️⃣ 1️⃣", "text": "Angka apa pun dikali 1 hasilnya angka itu sendiri.\nAngka apa pun dikali 0 hasilnya 0."}]$j$::jsonb,$j$[{"q": "3 × 4 = ?", "options": ["7", "12", "10", "14"], "answer": 1}, {"q": "5 + 5 + 5 sama dengan …", "options": ["3 × 5", "5 × 5", "5 + 3"], "answer": 0}, {"q": "7 × 0 = ?", "options": ["7", "0", "1"], "answer": 1}, {"q": "6 × 3 = ?", "options": ["18", "16", "9", "21"], "answer": 0}, {"q": "Ada 4 kotak pensil. Tiap kotak berisi 6 pensil. Berapa semua pensil?", "options": ["10", "20", "24", "30"], "answer": 2}, {"q": "8 × 5 = ?", "options": ["35", "40", "45", "13"], "answer": 1}]$j$::jsonb),
('pecahan','Mengenal Pecahan','🍕','sun',2,'id',$j$[{"emoji": "🍕", "text": "Pecahan adalah bagian dari satu benda utuh yang dibagi sama besar."}, {"emoji": "🌓", "text": "Satu benda dibagi 2 sama besar.\nSatu bagiannya disebut setengah, ditulis 1/2."}, {"emoji": "🍰🍰🍰🍰", "text": "Kue dibagi 4 sama besar.\nSatu bagian = 1/4 (seperempat).\nDua bagian = 2/4, sama dengan 1/2."}]$j$::jsonb,$j$[{"q": "Pizza dibagi 2 sama besar. Satu bagian disebut …", "options": ["1/2", "1/4", "2/1"], "answer": 0}, {"q": "Roti dibagi 4 sama besar, Arka makan 1. Pecahannya …", "options": ["1/2", "1/4", "4/1"], "answer": 1}, {"q": "Mana yang lebih besar?", "options": ["1/2", "1/4"], "answer": 0}, {"q": "2/4 sama dengan …", "options": ["1/4", "1/2", "1"], "answer": 1}, {"q": "Semangka dibagi 3 sama besar. Satu bagiannya …", "options": ["1/3", "1/2", "3/1"], "answer": 0}]$j$::jsonb),
('daily-routine','My Daily Routine','⏰','ocean',3,'en',$j$[{"emoji": "🌅", "text": "I wake up at six o'clock.\nThen I take a bath and brush my teeth."}, {"emoji": "🍳", "text": "I eat breakfast at half past six.\nI go to school at seven o'clock."}, {"emoji": "📚", "text": "In the afternoon, I do my homework.\nAt night, I go to bed at nine o'clock."}]$j$::jsonb,$j$[{"q": "What time does he wake up?", "options": ["🕕 Six o'clock", "🕘 Nine o'clock", "🕖 Seven o'clock"], "answer": 0}, {"q": "\"Sarapan\" in English is …", "options": ["Lunch", "Breakfast", "Dinner"], "answer": 1}, {"q": "I ___ my teeth.", "options": ["brush", "eat", "sleep"], "answer": 0}, {"q": "When does he do his homework?", "options": ["In the morning", "In the afternoon", "At midnight"], "answer": 1}, {"q": "\"Half past six\" is …", "options": ["6:30", "6:15", "7:30"], "answer": 0}]$j$::jsonb),
('wujud-benda','Wujud Benda','🧊','teal',4,'id',$j$[{"emoji": "🧱", "text": "Benda padat bentuknya tetap.\nContoh: batu, buku, pensil."}, {"emoji": "🥛", "text": "Benda cair bentuknya mengikuti wadah.\nContoh: air, susu, minyak."}, {"emoji": "🎈", "text": "Benda gas memenuhi ruangan dan biasanya tidak terlihat.\nContoh: udara di dalam balon."}, {"emoji": "🧊➡️💧", "text": "Wujud benda bisa berubah.\nEs batu yang dipanaskan mencair menjadi air."}]$j$::jsonb,$j$[{"q": "Batu termasuk benda …", "options": ["Padat", "Cair", "Gas"], "answer": 0}, {"q": "Benda yang bentuknya mengikuti wadah adalah benda …", "options": ["Padat", "Cair", "Gas"], "answer": 1}, {"q": "Udara di dalam balon adalah benda …", "options": ["Cair", "Gas", "Padat"], "answer": 1}, {"q": "Es batu yang dibiarkan di luar akan …", "options": ["Membeku", "Mencair", "Menguap jadi batu"], "answer": 1}, {"q": "Mana yang termasuk benda cair?", "options": ["🥛 Susu", "📕 Buku", "✏️ Pensil"], "answer": 0}]$j$::jsonb),
('animals-en','Animals Around Us','🦒','grass',5,'en',$j$[{"emoji": "🦒", "text": "A giraffe has a very long neck.\nIt eats leaves from tall trees."}, {"emoji": "🐬", "text": "A dolphin lives in the sea.\nIt is smart and can jump high."}, {"emoji": "🦉", "text": "An owl sleeps in the day and is awake at night."}]$j$::jsonb,$j$[{"q": "Which animal has a long neck?", "options": ["🦒 Giraffe", "🐬 Dolphin", "🦉 Owl"], "answer": 0}, {"q": "Where does a dolphin live?", "options": ["In the forest", "In the sea", "In the desert"], "answer": 1}, {"q": "An owl is awake at …", "options": ["night", "noon", "morning"], "answer": 0}, {"q": "\"Leher\" in English is …", "options": ["Leg", "Neck", "Nose"], "answer": 1}]$j$::jsonb),
('healthy-food-1','Healthy Food','🥦','grass',6,'en',$j$[{"image": "img/hf/intro.jpg", "text": "Look at the pictures. What do you think about these foods?"}, {"video": "fE8lezHs19s", "text": "Let's watch! 🎬"}, {"video": "e1wLP6hByEE", "text": "Let's watch one more! 🎬"}, {"image": "img/hf/healthy-all.jpg", "text": "Healthy food helps our body to be strong.\nFor example: rice, fish, egg, chicken, beans, soup, fruits, vegetables, and milk."}, {"image": "img/hf/unhealthy-all.jpg", "text": "Unhealthy food tastes yummy, but it does not make our body strong.\nFor example: candy, chocolate, ice cream, fizzy drinks, burgers, and French fries.\nWe eat them only sometimes."}, {"image": "img/hf/ahmed.jpg", "text": "Ahmed loves healthy food because it makes his body feel good.\nHis mother often cooks healthy meals for him, and Ahmed likes to help her in the kitchen.\nEvery day he eats many fruits and vegetables, so he can grow smart, healthy, and strong."}, {"image": "img/hf/albaqarah.jpg", "text": "Islamic Value 🕌\nIn Surah Al-Baqarah verse 168, Allah tells us to eat food that is halal and good (halalan thayyiban)."}]$j$::jsonb,$j$[{"video": "fE8lezHs19s", "q": "Watch the video again. Which food makes our body healthy?", "options": ["🥦🍎 Vegetables and fruits", "🍬 Lots of candy", "🥤 Fizzy drinks every day"], "answer": 0}, {"video": "e1wLP6hByEE", "q": "Watch again. What is a good habit?", "options": ["Eating fruit and vegetables every day", "Eating chips for breakfast", "Drinking soda all the time"], "answer": 0}, {"image": "img/hf/intro.jpg", "q": "Look at the picture. Which side shows healthy food?", "options": ["The green thumbs-up side 👍", "The red thumbs-down side 👎"], "answer": 0}, {"image": "img/hf/tomato.jpg", "q": "What is this? Is it healthy?", "options": ["It is a tomato. It is healthy.", "It is an apple. It is unhealthy.", "It is a tomato. It is unhealthy."], "answer": 0}, {"image": "img/hf/carrot.jpg", "q": "This vegetable is orange and long. What is it?", "options": ["A carrot", "A banana", "A corn"], "answer": 0}, {"image": "img/hf/fizzy.jpg", "q": "Look at the picture. What are these?", "options": ["Fizzy drinks", "Glasses of milk", "Bowls of soup"], "answer": 0}, {"image": "img/hf/burger.jpg", "q": "Is a burger healthy food?", "options": ["No, it is unhealthy food.", "Yes, it is healthy food."], "answer": 0}, {"image": "img/hf/fries.jpg", "q": "French fries taste good, but they are …", "options": ["unhealthy food", "healthy food"], "answer": 0}, {"image": "img/hf/pear.jpg", "q": "Healthy or unhealthy?", "options": ["Healthy 👍", "Unhealthy 👎"], "answer": 0}, {"image": "img/hf/cookies.jpg", "q": "Healthy or unhealthy?", "options": ["Healthy 👍", "Unhealthy 👎"], "answer": 1}, {"image": "img/hf/greenbeans.jpg", "q": "Healthy or unhealthy?", "options": ["Healthy 👍", "Unhealthy 👎"], "answer": 0}, {"image": "img/hf/soda.jpg", "q": "Healthy or unhealthy?", "options": ["Healthy 👍", "Unhealthy 👎"], "answer": 1}, {"passage": "Ahmed loves healthy food because it makes his body feel good.\nHis mother often cooks healthy meals for him, and Ahmed likes to help her in the kitchen.\nEvery day he eats many fruits and vegetables, so he can grow smart, healthy, and strong.", "q": "Why does Ahmed love healthy food?", "options": ["It makes his body feel good", "It is very sweet", "It is very cheap"], "answer": 0}, {"passage": "Ahmed loves healthy food because it makes his body feel good.\nHis mother often cooks healthy meals for him, and Ahmed likes to help her in the kitchen.\nEvery day he eats many fruits and vegetables, so he can grow smart, healthy, and strong.", "q": "Who cooks healthy meals for Ahmed?", "options": ["👩 His mother", "👨‍🏫 His teacher", "👦 His friend"], "answer": 0}, {"image": "img/hf/albaqarah.jpg", "q": "Al-Baqarah verse 168 tells us to eat food that is …", "options": ["halal and good", "sweet and cold", "big and expensive"], "answer": 0}]$j$::jsonb),
('healthy-food-2','Our Favourite Food','🍉','coral',7,'en',$j$[{"video": "ddDN30evKPc", "text": "Let's watch! 🎬"}, {"video": "2U4kYVXEgXw", "text": "Let's watch one more! 🎬"}, {"image": "img/hf/like-table.jpg", "text": "Like and dislike\nI like … / I don't like …\nShe likes … / She doesn't like …\nHe likes … / He doesn't like …"}, {"image": "img/hf/toast.jpg", "text": "Hi! I am Musa. My big sister is Aisyah, and my little brother is Harun.\nOn school days, I eat toast with jam and drink chocolate milk for breakfast.\nAisyah does not drink chocolate milk. She enjoys rice and egg in the morning.\nHarun loves fish! He does not like egg. He eats fish with rice or fish with potato.\nWe all love fruit, especially watermelon."}, {"image": "img/hf/cloud-musa.jpg", "text": "Look at the thinking clouds.\nA food with ❌ is a food they don't like."}]$j$::jsonb,$j$[{"video": "ddDN30evKPc", "q": "Watch the video again. Choose the correct sentence.", "options": ["I like apples.", "I likes apples."], "answer": 0}, {"video": "2U4kYVXEgXw", "q": "Watch again. Choose the correct sentence about a girl.", "options": ["She likes bananas.", "She like bananas."], "answer": 0}, {"image": "img/hf/like-table.jpg", "q": "Look at the table. Aisyah … pizza.", "options": ["doesn't like", "likes"], "answer": 0}, {"image": "img/hf/like-table.jpg", "q": "Look at the table. What does Harun like?", "options": ["🐟 Fish", "🍔 Burger", "🍬 Candy"], "answer": 0}, {"image": "img/hf/cloud-musa.jpg", "q": "Look at Musa's cloud. Which food does Musa NOT like?", "options": ["🍳 Egg", "🍉 Watermelon", "🍞 Toast"], "answer": 0}, {"image": "img/hf/cloud-aisyah.jpg", "q": "Look at Aisyah's cloud. Which sentence is correct?", "options": ["She doesn't like candy.", "She likes candy.", "She doesn't like bananas."], "answer": 0}, {"image": "img/hf/cloud-harun.jpg", "q": "Look at Harun's cloud. He likes oranges and fish, but he doesn't like …", "options": ["🍕 pizza", "🐟 fish", "🍊 oranges"], "answer": 0}, {"image": "img/hf/toast.jpg", "passage": "Hi! I am Musa. My big sister is Aisyah, and my little brother is Harun.\nOn school days, I eat toast with jam and drink chocolate milk for breakfast.\nAisyah does not drink chocolate milk. She enjoys rice and egg in the morning.\nHarun loves fish! He does not like egg. He eats fish with rice or fish with potato.\nWe all love fruit, especially watermelon.", "q": "What does Musa eat for breakfast on school days?", "options": ["Toast with jam", "Rice and egg", "Fish and potato"], "answer": 0}, {"passage": "Hi! I am Musa. My big sister is Aisyah, and my little brother is Harun.\nOn school days, I eat toast with jam and drink chocolate milk for breakfast.\nAisyah does not drink chocolate milk. She enjoys rice and egg in the morning.\nHarun loves fish! He does not like egg. He eats fish with rice or fish with potato.\nWe all love fruit, especially watermelon.", "q": "What does Aisyah NOT drink?", "options": ["Chocolate milk", "Water", "Orange juice"], "answer": 0}, {"image": "img/hf/fish.jpg", "passage": "Hi! I am Musa. My big sister is Aisyah, and my little brother is Harun.\nOn school days, I eat toast with jam and drink chocolate milk for breakfast.\nAisyah does not drink chocolate milk. She enjoys rice and egg in the morning.\nHarun loves fish! He does not like egg. He eats fish with rice or fish with potato.\nWe all love fruit, especially watermelon.", "q": "Harun loves …", "options": ["fish", "egg", "candy"], "answer": 0}, {"image": "img/hf/watermelon.jpg", "passage": "Hi! I am Musa. My big sister is Aisyah, and my little brother is Harun.\nOn school days, I eat toast with jam and drink chocolate milk for breakfast.\nAisyah does not drink chocolate milk. She enjoys rice and egg in the morning.\nHarun loves fish! He does not like egg. He eats fish with rice or fish with potato.\nWe all love fruit, especially watermelon.", "q": "Which fruit do they all love?", "options": ["Watermelon", "Apple", "Grapes"], "answer": 0}, {"q": "Choose the correct sentence about Harun.", "emoji": "👦🥚❌", "options": ["He doesn't like egg.", "He don't like egg.", "He not like egg."], "answer": 0}]$j$::jsonb)
on conflict (id) do update set title=excluded.title, emoji=excluded.emoji, color=excluded.color,
  sort_order=excluded.sort_order, lang=excluded.lang, pages=excluded.pages, questions=excluded.questions;

update lessons set subject = 'mtk'  where id in ('perkalian','pecahan') and subject is null;
update lessons set subject = 'ipas' where id = 'wujud-benda' and subject is null;
update lessons set subject = 'bing' where id in ('daily-routine','animals-en','healthy-food-1','healthy-food-2') and subject is null;

insert into lessons (id,subject,title,emoji,color,sort_order,lang,pages,questions) values
('pecahan-pizza','mtk','Pecahan Pizza','🍕','sun',3,'id',$j$[{"pizza": {"n": 2, "labels": true}, "text": "Satu pizza dibagi menjadi 2 bagian sama besar.\nSetiap potong adalah 1/2 (setengah)."}, {"pizza": {"n": 3, "labels": true}, "text": "Satu pizza dibagi menjadi 3 bagian sama besar.\nSetiap potong adalah 1/3 (sepertiga)."}, {"pizza": {"n": 4, "labels": true}, "text": "Satu pizza dibagi menjadi 4 bagian sama besar.\nSetiap potong adalah 1/4 (seperempat)."}, {"pizza": {"n": 6, "labels": true}, "text": "Satu pizza dibagi menjadi 6 bagian sama besar.\nSetiap potong adalah 1/6 (seperenam)."}, {"pizza": {"n": 8, "labels": true}, "text": "Satu pizza dibagi menjadi 8 bagian sama besar.\nSetiap potong adalah 1/8 (seperdelapan)."}, {"pizza": {"n": 4, "take": 3}, "text": "Kalau kita punya 3 potong dari pizza yang dibagi 4, pecahannya 3/4.\nAngka bawah = semua potong. Angka atas = potong yang kita punya."}]$j$::jsonb,$j$[{"pizza": {"n": 2}, "q": "Satu pizza dibagi menjadi 2 bagian sama besar. Setiap potong pizza dinyatakan dengan pecahan …", "options": ["1/2", "1/3", "2/1"], "answer": 0}, {"pizza": {"n": 3}, "q": "Satu pizza dibagi menjadi 3 bagian sama besar. Setiap potong pizza dinyatakan dengan pecahan …", "options": ["1/3", "1/2", "3/1"], "answer": 0}, {"pizza": {"n": 4}, "q": "Satu pizza dibagi menjadi 4 bagian sama besar. Setiap potong pizza dinyatakan dengan pecahan …", "options": ["1/4", "1/2", "4/1"], "answer": 0}, {"pizza": {"n": 6}, "q": "Satu pizza dibagi menjadi 6 bagian sama besar. Setiap potong pizza dinyatakan dengan pecahan …", "options": ["1/6", "1/8", "6/1"], "answer": 0}, {"pizza": {"n": 8}, "q": "Satu pizza dibagi menjadi 8 bagian sama besar. Setiap potong pizza dinyatakan dengan pecahan …", "options": ["1/8", "1/6", "8/1"], "answer": 0}, {"pizza": {"n": 8}, "q": "Lihat pizza di sebelah kanan. Pizza ini dibagi menjadi berapa bagian sama besar?", "options": ["8", "6", "4"], "answer": 0}, {"pizza": {"n": 4, "take": 2}, "q": "Berapa bagian pizza yang berwarna?", "options": ["2/4", "1/4", "4/2"], "answer": 0}, {"pizza": {"n": 6, "take": 5}, "q": "Berapa bagian pizza yang berwarna?", "options": ["5/6", "1/6", "6/5"], "answer": 0}, {"pizza": {"n": 8, "take": 3}, "q": "Berapa bagian pizza yang berwarna?", "options": ["3/8", "5/8", "8/3"], "answer": 0}, {"pizza": {"n": 3, "take": 2}, "q": "Berapa bagian pizza yang berwarna?", "options": ["2/3", "1/3", "3/2"], "answer": 0}, {"pizza": {"n": 3, "take": 1}, "q": "Mama membeli pizza dan meminta Arka memotongnya menjadi 3 bagian sama besar. Arka memberikan 1 potong kepada temannya, Raka.\nBerapa bagian pizza yang diterima Raka?", "options": ["1/3", "1/2", "3/1"], "answer": 0}, {"pizza": {"n": 4, "take": 1}, "q": "Nenek memberi Mama 1 pizza. Mama meminta Arka memotong pizza menjadi 4 bagian sama besar, lalu memberikan 1 bagian kepada Ayah.\nBerapa bagian pizza yang diterima Ayah?", "options": ["1/4", "1/3", "4/1"], "answer": 0}, {"pizza": {"n": 2, "take": 1}, "q": "Arka dan Mama berbagi 1 pizza sama rata.\nBerapa bagian pizza yang didapat Arka?", "options": ["1/2", "1/4", "2/1"], "answer": 0}, {"pizza": {"n": 6, "take": 2}, "q": "Pizza dipotong menjadi 6 bagian sama besar. Arka makan 2 potong.\nBerapa bagian pizza yang dimakan Arka?", "options": ["2/6", "1/6", "6/2"], "answer": 0}, {"pizza": {"n": 8, "take": 4}, "q": "Pizza dipotong menjadi 8 bagian sama besar. Arka dan 3 temannya masing-masing makan 1 potong.\nBerapa bagian pizza yang sudah dimakan?", "options": ["4/8", "1/8", "3/8"], "answer": 0}, {"pizza": {"n": 4, "take": 3}, "q": "Pizza dipotong menjadi 4 bagian sama besar. Arka makan 1 potong. Potong yang berwarna adalah sisanya.\nBerapa bagian pizza yang tersisa?", "options": ["3/4", "1/4", "4/3"], "answer": 0}, {"emoji": "🍕🤔", "q": "Mana yang lebih besar: 1 potong dari pizza yang dibagi 2, atau 1 potong dari pizza yang dibagi 8?", "options": ["1/2", "1/8"], "answer": 0}]$j$::jsonb)
on conflict (id) do update set subject=excluded.subject, title=excluded.title, emoji=excluded.emoji, color=excluded.color,
  sort_order=excluded.sort_order, lang=excluded.lang, pages=excluded.pages, questions=excluded.questions;

-- Pelajaran Pecahan Bergambar (6 bagian)
insert into lessons (id,subject,title,emoji,color,sort_order,lang,pages,questions) values
('pecahan-gambar','mtk','Pecahan Bergambar','🍰','coral',4,'id',$j$[{"sec": "1. Mengenal Pecahan", "text": "Ini 1 kue utuh.\nKalau kue dibagi menjadi beberapa potong yang sama besar, setiap potongnya disebut pecahan.", "shape": {"type": "circle", "n": 1, "food": "cake", "gap": true}}, {"sec": "1. Mengenal Pecahan", "text": "Kue dibagi 2 sama besar.\nSetiap potong bernilai 1/2 (seperdua atau setengah).", "shape": {"type": "circle", "n": 2, "food": "cake", "gap": true}}, {"sec": "1. Mengenal Pecahan", "text": "Semangka dibagi 4 sama besar.\nSetiap potong bernilai 1/4 (seperempat).", "shape": {"type": "circle", "n": 4, "food": "watermelon", "gap": true}}, {"sec": "1. Mengenal Pecahan", "text": "Ingat!\nAngka bawah = banyak semua potongan.\nAngka atas = potongan yang kita ambil.\nDonat dibagi 3, satu potongnya 1/3.", "shape": {"type": "circle", "n": 3, "food": "donut", "gap": true}}, {"sec": "2. Bagian yang Berwarna", "text": "Lingkaran ini dibagi 4 sama besar.\n1 bagian diwarnai kuning.\nPecahannya 1/4.", "shape": {"type": "circle", "n": 4, "color": "kuning", "fill": [2]}}, {"sec": "2. Bagian yang Berwarna", "text": "Persegi panjang ini dibagi 4 sama besar.\nYang berwarna ungu ada 2.\nPecahannya 2/4.", "shape": {"type": "rect", "color": "ungu", "n": 4, "fill": [1, 3], "dir": "h"}}, {"sec": "2. Bagian yang Berwarna", "text": "Cara membaca gambar:\n1. Hitung bagian yang berwarna → angka atas.\n2. Hitung semua bagian → angka bawah.\nDi sini 3 dari 6 berwarna, jadi 3/6.", "shape": {"type": "circle", "n": 6, "color": "hijau", "fill": [0, 2, 4]}}, {"sec": "3. Pecahan dalam Kata", "text": "Pecahan juga bisa ditulis dengan kata:\n1/2 = seperdua (setengah)\n1/3 = sepertiga\n1/4 = seperempat\n1/5 = seperlima\n1/6 = seperenam\n1/8 = seperdelapan", "emoji": "✏️📖"}, {"sec": "3. Pecahan dalam Kata", "text": "Kalau angka atasnya lebih dari 1:\n2/3 dibaca dua pertiga\n3/4 dibaca tiga perempat\n2/6 dibaca dua per enam", "shape": {"type": "circle", "n": 3, "color": "biru", "fill": [0, 1]}}, {"sec": "4. Memilih Gambar yang Tepat", "text": "Di bagian ini, pilihan jawabannya berupa gambar.\nBaca pecahannya, lalu cari gambar yang bagian berwarnanya cocok.\nContoh: 1/4 artinya 1 bagian berwarna dari 4 bagian sama besar.", "shape": {"type": "circle", "n": 4, "color": "oranye", "fill": [0]}}, {"sec": "5. Pecahan Senilai", "text": "Lihat ketiga lingkaran ini.\n1/2, 2/4, dan 4/8 bagian berwarnanya sama besar.\nPecahan seperti ini disebut pecahan senilai.\n1/2 = 2/4 = 4/8", "shapes": [{"type": "circle", "n": 2, "color": "biru", "fill": [0]}, {"type": "circle", "n": 4, "color": "biru", "fill": [0, 1]}, {"type": "circle", "n": 8, "color": "biru", "fill": [0, 1, 2, 3]}]}, {"sec": "5. Pecahan Senilai", "text": "1/3 dan 2/6 juga senilai.\nBagian berwarnanya sama panjang.", "shapes": [{"type": "rect", "color": "hijau", "n": 3, "fill": [0]}, {"type": "rect", "color": "hijau", "n": 6, "fill": [0, 1]}]}, {"sec": "6. Soal Cerita", "text": "Cara mengerjakan soal cerita pecahan:\n1. Cari benda dibagi menjadi berapa bagian sama besar → angka bawah.\n2. Cari berapa bagian yang diambil, dimakan, atau diberikan → angka atas.", "emoji": "📖✏️"}]$j$::jsonb,$j$[{"sec": "1. Mengenal Pecahan", "q": "Setiap potongan donat bernilai …", "options": ["1/3", "1/4", "1/2"], "answer": 0, "shape": {"type": "circle", "n": 3, "food": "donut", "gap": true}}, {"sec": "1. Mengenal Pecahan", "q": "Setiap potongan kue bernilai …", "options": ["1/2", "1/4", "1/3"], "answer": 0, "shape": {"type": "circle", "n": 2, "food": "cake", "gap": true}}, {"sec": "1. Mengenal Pecahan", "q": "Setiap potongan semangka bernilai …", "options": ["1/8", "1/6", "1/4"], "answer": 0, "shape": {"type": "circle", "n": 8, "food": "watermelon", "gap": true}}, {"sec": "1. Mengenal Pecahan", "q": "Setiap potongan kue bernilai …", "options": ["1/6", "1/8", "1/7"], "answer": 0, "shape": {"type": "circle", "n": 6, "food": "cake", "gap": true}}, {"sec": "1. Mengenal Pecahan", "q": "Kue tart ini dipotong sama besar. Setiap poto