3/5"], "answer": 0, "shape": {"type": "poly", "color": "oranye", "n": 5, "fill": [0, 2]}}, {"sec": "2. Bagian yang Berwarna", "q": "Bagian yang berwarna kuning menunjukkan pecahan …", "options": ["3/8", "3/7", "3/6"], "answer": 0, "shape": {"type": "circle", "n": 8, "color": "kuning", "fill": [1, 4, 6]}}, {"sec": "2. Bagian yang Berwarna", "q": "Bintang ini dibagi 5 sama besar. Bagian yang berwarna pink menunjukkan pecahan …", "options": ["3/5", "2/5", "5/3"], "answer": 0, "shape": {"type": "star", "color": "pink", "fill": [0, 1, 3]}}, {"sec": "2. Bagian yang Berwarna", "q": "Bagian yang berwarna toska menunjukkan pecahan …", "options": ["2/6", "2/4", "4/6"], "answer": 0, "shape": {"type": "rect", "color": "toska", "fill": [0, 4], "rows": 2, "cols": 3}}, {"sec": "3. Pecahan dalam Kata", "q": "Sebuah kue tart dibagi 2 sama besar. Satu potong tart disebut …", "options": ["seperdua", "sepertiga", "seperempat"], "answer": 0, "shape": {"type": "circle", "n": 2, "food": "tart", "gap": true}}, {"sec": "3. Pecahan dalam Kata", "q": "Berapa bagian satu potong pizza?", "options": ["seperdelapan", "seperenam", "sepertujuh"], "answer": 0, "pizza": {"n": 8}}, {"sec": "3. Pecahan dalam Kata", "q": "Sebuah jeruk dibagi 4 sama besar. Satu potongnya disebut …", "options": ["seperempat", "seperlima", "sepertiga"], "answer": 0, "shape": {"type": "circle", "n": 4, "food": "orange", "gap": true}}, {"sec": "3. Pecahan dalam Kata", "q": "Satu potong kue tart ini disebut …", "options": ["seperenam", "seperdelapan", "seperempat"], "answer": 0, "shape": {"type": "circle", "n": 6, "food": "tart", "gap": true}}, {"sec": "3. Pecahan dalam Kata", "q": "Sebatang cokelat dibagi 5 sama besar. Satu potong cokelat disebut …", "options": ["seperlima", "seperenam", "sepertiga"], "answer": 0, "shape": {"type": "rect", "color": "merah", "n": 5, "food": "choco"}}, {"sec": "3. Pecahan dalam Kata", "q": "Satu potong donat ini disebut …", "options": ["sepertiga", "seperdua", "seperempat"], "answer": 0, "shap